      value = x;
    }
  }

  static class QueueDS {
    Node head, tail;

    void offer(int x) {
      Node n = new Node(x);
      if (tail == null) head = n;
      else tail.next = n;
      tail = n;
    }

    int poll() {
      if (head == null) throw new NoSuchElementException();
      int x = head.value;
      head = head.next;
      if (head == null) tail = null;
      return x;
    }
  }

  public static void main(String[] args) {
